import React, { useEffect, useRef, useState } from "react";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const rippleRef = useRef(null);

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
  }, []);

  const generateImage = (imagePaths) => {
    // your image generation code remains the same...
    // (to keep it short here — let me know if you want the full block pasted again!)
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    generateImage(imagePaths);
  };

  // Ripple animation effect
  const handleMouseMove = (e) => {
    if (!rippleRef.current || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    rippleRef.current.style.left = `${x}px`;
    rippleRef.current.style.top = `${y}px`;
    rippleRef.current.classList.remove("animate");
    void rippleRef.current.offsetWidth; // reset animation
    rippleRef.current.classList.add("animate");
  };

  return (
    <div>
      <h1>Generated Image</h1>

      <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", marginBottom: "1rem" }}>
        {imagePaths.map((src, index) => (
          <div key={index} style={{ textAlign: "center" }}>
            <p>{index + 1}번째 이미지</p>
            <img src={src} width={100} alt={`img-${index}`} />
          </div>
        ))}
      </div>

      <div
        ref={containerRef}
        onMouseMove={handleMouseMove}
        onTouchMove={(e) => {
          const touch = e.touches[0];
          handleMouseMove({ clientX: touch.clientX, clientY: touch.clientY });
        }}
        style={{
          position: "relative",
          display: "inline-block",
          width: 1080,
          height: 1080,
          border: "1px solid #555",
          marginBottom: "1rem",
          overflow: "hidden",
        }}
      >
        <canvas ref={canvasRef} width={1080} height={1080} />
        <div
          ref={rippleRef}
          style={{
            position: "absolute",
            width: 200,
            height: 200,
            background: "radial-gradient(circle, rgba(255,214,102,0.4) 0%, transparent 70%)",
            borderRadius: "50%",
            pointerEvents: "none",
            transform: "translate(-50%, -50%) scale(0)",
            transition: "transform 0.4s ease-out",
          }}
          className=""
        />
      </div>

      <div style={{ display: "flex", gap: "1rem" }}>
        <button onClick={handleRegenerate}>🔁 Regenerate</button>
        <button onClick={handleDownload}>⬇️ Download</button>
      </div>

      <style>{`
        .animate {
          transform: translate(-50%, -50%) scale(1);
        }
      `}</style>
    </div>
  );
}

export default Generate;
